#!/usr/bin/env python3
# Гл. 7, G3: «и, и, и» избирательно. Оставлены: 577 (падение, действия подряд), 599 (Ханна поднимает — одно движение), 127 (её оговорка).
import pathlib
p = pathlib.Path("03-manuscript/arc-02/ch-07.md")
t = p.read_text(encoding="utf-8"); n = 0
def rep(old, new):
    global t, n
    c = t.count(old); assert c == 1, f"count={c}: {old[:70]!r}"
    t = t.replace(old, new); n += 1
rep("Сидеть я научилась накануне вечером, и научилась дорого: на это ушло четыре попытки и половина вечера, и после четвёртой я полежала в темноте, дожидаясь, пока перестанет звенеть в ушах.",
    "Сидеть я научилась накануне вечером, и научилась дорого: четыре попытки, половина вечера. После четвёртой я полежала в темноте, дожидаясь, пока перестанет звенеть в ушах.")
rep("Она записала что-то на карточке, висевшей у изголовья, и я успела рассмотреть, что записывает она значками, а не словами, и значков там было немного, штук шесть, и повторялись они изо дня в день.",
    "Она записала что-то на карточке, висевшей у изголовья. Записывала она значками, не словами; значков было немного, штук шесть, и повторялись они изо дня в день.")
rep("После её ухода мне оставалось ждать, и ждать долго: между завтраком и вторым осмотром в этом крыле умещается вся утренняя работа целиком, и я прослушала её от начала до конца через дверь.",
    "После её ухода мне оставалось ждать, и ждать долго: между завтраком и вторым осмотром в этом крыле умещается вся утренняя работа целиком. Я прослушала её от начала до конца через дверь.")
rep("Я села, дотянулась до кувшина, налила себе воды и выпила, и это заняло много времени, потребовало полного внимания, и пока длилось, было легче.",
    "Я села, дотянулась до кувшина, налила себе воды и выпила. Это заняло много времени, потребовало полного внимания, и пока длилось, было легче.")
rep("Скорее всего, пришла и забрала, и он сейчас сидит у неё на подоконнике и объедает её сверх всякой меры.",
    "Скорее всего, пришла и забрала. Он сейчас сидит у неё на подоконнике и объедает её сверх всякой меры.")
rep("Мать получает сведения из Минты, и я могла бы попросить её узнать, и она, скорее всего, узнала бы.",
    "Мать получает сведения из Минты. Я могла бы попросить её узнать, и она, скорее всего, узнала бы.")
rep("Он спал у меня в ногах и занимал середину, и подвинуть его было нельзя: он делался вдвое тяжелее и как-то ухитрялся при этом не проснуться.",
    "Он спал у меня в ногах и занимал середину. Подвинуть его было нельзя: он делался вдвое тяжелее и как-то ухитрялся при этом не проснуться.")
rep("На третьем кровать кончилась, и я осталась стоять посреди комнаты без опоры, и обнаружила, что стою.",
    "На третьем кровать кончилась. Я осталась стоять посреди комнаты без опоры и обнаружила, что стою.")
rep("Ханна что-то говорила, и я слышала её через слой, и разбирала одно слово из трёх.",
    "Ханна что-то говорила. Я слышала её через слой и разбирала одно слово из трёх.")
p.write_text(t, encoding="utf-8"); print("replacements:", n)
